import {animateDraw,METHODS} from './random-methods.js';
const $=id=>document.getElementById(id);
export const MODE_CAPS={normal:4,lockdown:5,forbidden:6};
const roles={assault:['Assault Rifle','Light Machine Gun'],close:['Submachine Gun','Shotgun'],precision:['Marksman Rifle','Bolt-Action Rifle','Carbine'],pistol:['Pistol']};
export function pick(list,random=Math.random){if(!list.length)throw new Error('ไม่มีไอเท็มตรงตัวกรอง');return list[Math.floor(random()*list.length)];}
export function weaponPool(db,{mode='normal',role='any',tier=4}={}){
 const cap=MODE_CAPS[mode];if(!cap)throw new Error('โหมดไม่ถูกต้อง');
 return db.weapons.filter(w=>(role==='any'||roles[role]?.includes(w.type))&&db.ammo.some(a=>a.caliber===w.caliber&&a.tier>=3&&a.tier<=cap));
}
export function generateKit(db,settings={},random=Math.random,selectedWeapon=null){
 const mode=settings.mode??'normal',cap=MODE_CAPS[mode],tier=Number(settings.tier??4);if(!cap||tier<3||tier>cap)throw new Error('ระดับเกราะเกินข้อจำกัดของโหมด');
 const pool=weaponPool(db,settings);const weapon=selectedWeapon??pick(pool,random);if(!pool.some(w=>w.id===weapon.id))throw new Error('ปืนไม่อยู่ในกลุ่มที่เลือก');
 const ammo=pick(db.ammo.filter(a=>a.caliber===weapon.caliber&&a.tier>=3&&a.tier<=cap),random);
 const helmet=pick(db.helmets.filter(i=>i.tier===tier),random);
 const armored=settings.armor==='armored'||(settings.armor!=='separate'&&random()<.5);
 const body=pick(db[armored?'armored-rigs':'body-armor'].filter(i=>i.tier===tier&&(!armored||i.slots>=10)),random);
 const rig=armored?null:pick(db['chest-rigs'].filter(i=>i.slots>=12),random);
 const backpack=pick(db.backpacks.filter(i=>i.slots>=20&&i.slots<=40),random);
 // Wiki does not expose headset fit rules. Keep headset out of the committed kit.
 const headset=null;
 const bolt=weapon.type==='Bolt-Action Rifle',shotgun=weapon.type==='Shotgun',automatic=/Full|Automatic/i.test(weapon.fireMode);
 const rounds=bolt?60:shotgun?60:automatic?180:120;
 return {mode,cap,tier,weapon,ammo,helmet,body,rig,backpack,headset,armored,rounds,magazines:shotgun?'โหลดในปืน + กระสุนสำรอง (ถ้าใช้แม็กกาซีน ให้เลือกที่ตรงรุ่น)':bolt?'โหลดในปืน + กระสุนสำรอง / แม็กกาซีนตรงรุ่น 1 ชิ้น':'แม็กกาซีนตรงรุ่น: 1 ชิ้นในปืน + สำรอง 2 ชิ้น',supplies:[{name:pick(['926 Rapid First Aid Kit','Standard First Aid Kit','E3 Military Medkit'],random),qty:2,where:'เสื้อริก / กระเป๋า'},{name:pick(['OPM Bandage','Field Bandage'],random),qty:2,where:'เสื้อริก / ช่องกระเป๋าเสื้อ'},{name:pick(['AP Painkiller','EX Painkiller'],random),qty:1,where:'เสื้อริก / ช่องกระเป๋าเสื้อ'},{name:pick(['Standard Military Surgical Kit','TMK Military Surgical Kit'],random),qty:1,where:'กระเป๋า / กล่องปลอดภัย'},{name:'Metal Splint',qty:1,where:'กระเป๋า'},{name:'Energy Drink',qty:2,where:'กระเป๋า'},{name:'อาหารที่มีในคลัง',qty:1,where:'กระเป๋า'},{name:'Smoke Grenade',qty:1,where:'เสื้อริก / ช่องกระเป๋าเสื้อ'},{name:pick(['M67 Frag Grenade','MK2 Frag Grenade'],random),qty:2,where:'เสื้อริก / ช่องกระเป๋าเสื้อ'}]};
}
export function initLoadout(){
 let db,kit=null,options=[],rotation=0,busy=false;const canvas=$('kit-wheel'),ctx=canvas.getContext('2d');
 const settings=()=>({mode:$('kit-mode').value,role:$('kit-role').value,tier:Number($('kit-tier').value),armor:$('kit-armor').value});
 function draw(){const size=640;canvas.width=canvas.height=size;const r=size/2-12,c=size/2,n=options.length||1;ctx.clearRect(0,0,size,size);ctx.save();ctx.translate(c,c);for(let i=0;i<n;i++){const start=-Math.PI/2+i*2*Math.PI/n,end=start+2*Math.PI/n;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,r,start,end);ctx.closePath();ctx.fillStyle=['#172b42','#24445f','#32647a','#458496'][i%4];ctx.fill();ctx.strokeStyle='#ffffff40';ctx.lineWidth=2;ctx.stroke();ctx.save();ctx.rotate((start+end)/2);ctx.translate(r*.61,0);ctx.rotate(Math.PI/2);ctx.fillStyle='#fff';ctx.font='600 23px Segoe UI';ctx.textAlign='center';const name=options[i]?.name.replace(/ Assault Rifle| Micro SMG| Rifle| Shotgun| Submachine Gun| Carbine/g,'')??'LOADOUT';ctx.fillText(name.length>20?name.slice(0,18)+'…':name,0,0);ctx.restore();}ctx.restore();}
 function prepare(){const method=METHODS[$('kit-method').value];$('kit-style-help').textContent=method.help;$('kit-spin').textContent=method.action;$('kit-wheel-frame').hidden=$('kit-method').value!=='wheel';$('kit-animation').hidden=$('kit-method').value==='wheel';$('kit-animation').replaceChildren();const cfg=settings(),cap=MODE_CAPS[cfg.mode];for(const o of $('kit-tier').options)o.disabled=Number(o.value)>cap;if(cfg.tier>cap)$('kit-tier').value=String(cap);const pool=weaponPool(db,settings());options=[...pool];for(let i=options.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[options[i],options[j]]=[options[j],options[i]];}options=options.slice(0,8);rotation=0;canvas.style.transition='none';canvas.style.transform='rotate(0deg)';draw();$('kit-status').textContent=`สุ่มได้ ${pool.length} / ${db.weapons.length} ปืน · ammo T3–T${cap} ตรง caliber`;$('kit-spin').disabled=!options.length;const list=$('kit-catalog');list.replaceChildren();for(const gun of [...pool].sort((a,b)=>a.name.localeCompare(b.name))){const link=document.createElement('a');link.textContent=gun.name;link.href=gun.source;link.target='_blank';link.rel='noopener';list.append(link);}$('kit-catalog-count').textContent=`รายชื่อปืนที่สุ่มได้ (${pool.length})`;}
 function card(label,item,detail){const box=document.createElement('article');box.className='kit-card';const img=document.createElement('img');img.src=item.image;img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>img.hidden=true;const content=document.createElement('div'),small=document.createElement('span'),a=document.createElement('a'),p=document.createElement('p');small.textContent=label;a.textContent=item.name;a.href=item.source;a.target='_blank';a.rel='noopener';p.textContent=detail;content.append(small,a,p);box.append(img,content);return box;}
 function render(){const out=$('kit-result');out.replaceChildren();out.append(card('ปืนที่สุ่มได้',kit.weapon,`${kit.weapon.caliber} · ${kit.weapon.type} · ใช้ปืนประกอบครบที่ยิงได้`),card('กระสุน',kit.ammo,`${kit.rounds} นัดรวมที่โหลดแล้ว · T${kit.ammo.tier} · เจาะ ${kit.ammo.penetration} · ${kit.ammo.caliber}`),card('หมวก',kit.helmet,`T${kit.helmet.tier} · ${kit.helmet.weight} kg · ${kit.helmet.coverage}`),card(kit.armored?'เกราะริก — ใช้แทนเกราะ + ริก':'เกราะ',kit.body,`T${kit.body.tier} · ${kit.body.weight} kg${kit.armored?' · '+kit.body.slots+' ช่อง':''}`));if(kit.rig)out.append(card('เสื้อริก',kit.rig,`${kit.rig.slots} ช่อง · ${kit.rig.weight} kg`));out.append(card('กระเป๋า',kit.backpack,`${kit.backpack.slots} ช่อง · ${kit.backpack.weight} kg`));
 $('kit-checklist').replaceChildren();for(const text of [kit.magazines,...kit.supplies.map(s=>`${s.name} ×${s.qty} — ${s.where}`),'ประกอบปืน ตรวจแม็กกาซีนตรงรุ่น และโหลดกระสุนก่อนเข้า Raid','ตรวจความทนทาน น้ำหนัก ช่องเก็บ และมูลค่าเข้าโหมดในเกม','หูฟัง / หน้ากาก: เลือกเพิ่มเมื่อเกมยืนยันว่าใส่กับหมวกนี้ได้']){const row=document.createElement('label'),check=document.createElement('input'),span=document.createElement('span');check.type='checkbox';span.textContent=text;row.append(check,span);$('kit-checklist').append(row);}
 $('kit-empty').hidden=true;$('kit-details').hidden=false;$('kit-copy').disabled=false;$('kit-status').textContent=`ชุดเดียวพร้อมจัดของ · ${kit.mode.toUpperCase()} · เกราะ T${kit.tier} · ammo T${kit.ammo.tier}`;
 }
 const controls=['kit-mode','kit-role','kit-tier','kit-armor','kit-method'];
 $('kit-spin').onclick=async()=>{if(busy||!db||!options.length)return;prepare();void canvas.offsetWidth;busy=true;kit=null;$('kit-details').hidden=true;$('kit-empty').hidden=false;$('kit-spin').disabled=true;controls.forEach(id=>$(id).disabled=true);$('kit-copy').disabled=true;$('kit-status').textContent='กำลังสุ่มชุด…';const method=$('kit-method').value,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 try{const cfg=settings();if(method==='wheel'){const index=Math.floor(Math.random()*options.length);kit=generateKit(db,cfg,Math.random,options[index]);const n=options.length,target=360-(index+.5)*360/n;rotation+=5*360+((target-rotation%360+360)%360);canvas.style.transition=reduced?'none':'transform 3s cubic-bezier(.14,.72,.15,1)';canvas.style.transform=`rotate(${rotation}deg)`;await new Promise(resolve=>setTimeout(resolve,reduced?0:3050));}else{kit=await animateDraw(method,$('kit-animation'),()=>generateKit(db,cfg),weaponPool(db,cfg),reduced);}render();}catch(e){$('kit-status').textContent=e.message;}finally{busy=false;$('kit-spin').disabled=false;controls.forEach(id=>$(id).disabled=false);}
 };
 controls.forEach(id=>$(id).onchange=()=>{if(!db||busy)return;kit=null;$('kit-details').hidden=true;$('kit-empty').hidden=false;$('kit-copy').disabled=true;prepare();});
 $('kit-copy').onclick=async()=>{if(!kit||busy)return;const lines=[`ABI raid kit — ${kit.mode}, T${kit.tier}`,kit.weapon.name,`${kit.ammo.name} ×${kit.rounds}`,kit.helmet.name,kit.body.name,kit.rig?.name,kit.backpack.name,kit.magazines,...kit.supplies.map(s=>`${s.name} ×${s.qty}`),'ตรวจแม็กกาซีน, ปืนประกอบครบ, ความทนทาน, น้ำหนัก และมูลค่าเข้าโหมดในเกม'].filter(Boolean);try{await navigator.clipboard.writeText(lines.join('\n'));$('kit-status').textContent='คัดลอกชุดแล้ว';}catch{$('kit-status').textContent='คัดลอกไม่ได้ กรุณาเลือกข้อความจากรายการ';}};
 fetch('./loadout-data.json').then(r=>{if(!r.ok)throw new Error('โหลดข้อมูลไม่ได้');return r.json();}).then(data=>{db=data;prepare();}).catch(e=>{$('kit-status').textContent=e.message;});
}
